import math

_ZONE_CENTERS = {"A": (2.0, 2.0), "B": (4.95, 3.2), "C": (8.0, 2.0)}
_ZONE_EXTENTS = {
    "A": (1.5, 2.5, 1.5, 2.5),
    "B": (4.25, 5.65, 2.8, 3.6),
    "C": (7.5, 8.5, 1.5, 2.5),
}

# Global state tracking for trigger times
last_trigger_time = {'A': None, 'B': None, 'C': None}

def _max_agent_force(sandbox):
    return 50.0

def _zone_center(sandbox, name):
    return _ZONE_CENTERS[name]

def is_inside_zone(sandbox, x, y, zone_name):
    x_min, x_max, y_min, y_max = _ZONE_EXTENTS[zone_name]
    return x_min <= x <= x_max and y_min <= y <= y_max

def build_agent(sandbox):
    return sandbox.get_agent_body()

def agent_action(sandbox, agent_body, step_count):
    global last_trigger_time
    bx = sandbox.get_barrier_x()
    mf = _max_agent_force(sandbox)
    next_sw = sandbox.get_next_required_switch()
    cooldown = sandbox.get_cooldown_remaining()
    steps_in_zone = sandbox.get_steps_in_current_zone()
    steps_required = sandbox.get_steps_required_to_trigger()
    delay = sandbox.get_barrier_delay_steps()
    triggered = sandbox.get_triggered_switches()

    if next_sw is None:
        vx, vy = sandbox.get_agent_velocity()
        sandbox.apply_agent_force(-5.5 * vx, -5.5 * vy)
        return

    if cooldown > 0:
        vx, vy = sandbox.get_agent_velocity()
        sandbox.apply_agent_force(-5.5 * vx, -5.5 * vy)
        return

    if next_sw == "A":
        tx, ty = _zone_center(sandbox, "A")
        x, y = sandbox.get_agent_position()
        dx = tx - x
        dy = ty - y
        dist = math.hypot(dx, dy)

        if dist > 0.5:
            force_mag = min(mf * 0.8, 20.0 * dist)
            fx = force_mag * dx / dist if dist > 1e-6 else 0
            fy = force_mag * dy / dist if dist > 1e-6 else 0
            sandbox.apply_agent_force(fx, fy)
        else:
            if is_inside_zone(sandbox, x, y, "A"):
                if "A" not in triggered:
                    if steps_in_zone == steps_required:
                        triggered.append("A")
                        last_trigger_time["A"] = step_count
                        next_sw = "B"
                    else:
                        sandbox.apply_agent_force(0, 0)
                        if delay > 0:
                            sandbox.apply_agent_force(0, 0)
                        else:
                            next_sw = "B"
                else:
                    sandbox.apply_agent_force(0, 0)
                    if delay > 0:
                        sandbox.apply_agent_force(0, 0)
                    else:
                        next_sw = "B"

    elif next_sw == "B":
        if last_trigger_time['A'] is not None and step_count - last_trigger_time['A'] <= 5000:
            # Check barrier status
            x, y = sandbox.get_agent_position()
            if bx - 0.08 <= x <= bx + 0.08 and delay > 0:
                # Agent in barrier's x range and barrier is closed
                if x < bx:
                    dx = -0.5
                else:
                    dx = 0.5
                tx, ty = _zone_center(sandbox, "B")
                dx_b = tx - x
                dy_b = ty - y
                dist_b = math.hypot(dx_b, dy_b)
                if dist_b > 0.5:
                    force_mag = min(mf * 0.8, 20.0 * dist_b)
                    fx = force_mag * dx_b / dist_b if dist_b > 1e-6 else 0
                    fy = force_mag * dy_b / dist_b if dist_b > 1e-6 else 0
                    sandbox.apply_agent_force(fx, fy)
                else:
                    sandbox.apply_agent_force(0, 0)
            else:
                tx, ty = _zone_center(sandbox, "B")
                x, y = sandbox.get_agent_position()
                dx = tx - x
                dy = ty - y
                dist = math.hypot(dx, dy)

                if dist > 0.5:
                    force_mag = min(mf * 0.8, 20.0 * dist)
                    fx = force_mag * dx / dist if dist > 1e-6 else 0
                    fy = force_mag * dy / dist if dist > 1e-6 else 0
                    sandbox.apply_agent_force(fx, fy)
                else:
                    if is_inside_zone(sandbox, x, y, "B"):
                        if "B" not in triggered:
                            if steps_in_zone == steps_required:
                                triggered.append("B")
                                last_trigger_time["B"] = step_count
                                next_sw = "C"
                            else:
                                sandbox.apply_agent_force(0, 0)
                                if cooldown > 0:
                                    sandbox.apply_agent_force(0, 0)
                                else:
                                    next_sw = "C"
                        else:
                            sandbox.apply_agent_force(0, 0)
                            if cooldown > 0:
                                sandbox.apply_agent_force(0, 0)
                            else:
                                next_sw = "C"
        else:
            # Cannot proceed to B, adjust movement to A
            tx, ty = _zone_center(sandbox, "A")
            x, y = sandbox.get_agent_position()
            dx = tx - x
            dy = ty - y
            dist = math.hypot(dx, dy)
            if dist > 0.5:
                force_mag = min(mf * 0.8, 20.0 * dist)
                fx = force_mag * dx / dist if dist > 1e-6 else 0
                fy = force_mag * dy / dist if dist > 1e-6 else 0
                sandbox.apply_agent_force(fx, fy)
            else:
                sandbox.apply_agent_force(0, 0)

    elif next_sw == "C":
        if last_trigger_time['B'] is not None and step_count - last_trigger_time['B'] <= 5000:
            x, y = sandbox.get_agent_position()
            if y < 3.5:
                # Need to move up to the platform
                tx, ty = _zone_center(sandbox, "C")
                dx = tx - x
                dy = ty - y
                dist = math.hypot(dx, dy)
                force_mag = min(mf * 0.8, 20.0 * dist)
                fx = force_mag * dx / dist if dist > 1e-6 else 0
                fy = force_mag * dy / dist if dist > 1e-6 else 0
                sandbox.apply_agent_force(fx, fy)
            else:
                tx, ty = _zone_center(sandbox, "C")
                x, y = sandbox.get_agent_position()
                dx = tx - x
                dy = ty - y
                dist = math.hypot(dx, dy)

                if dist > 0.5:
                    force_mag = min(mf * 0.8, 20.0 * dist)
                    fx = force_mag * dx / dist if dist > 1e-6 else 0
                    fy = force_mag * dy / dist if dist > 1e-6 else 0
                    sandbox.apply_agent_force(fx, fy)
                else:
                    if is_inside_zone(sandbox, x, y, "C"):
                        if "C" not in triggered:
                            if steps_in_zone == steps_required:
                                triggered.append("C")
                                last_trigger_time["C"] = step_count
                                next_sw = None
                            else:
                                sandbox.apply_agent_force(0, 0)
                                if cooldown > 0:
                                    sandbox.apply_agent_force(0, 0)
                                else:
                                    next_sw = "C"
                        else:
                            sandbox.apply_agent_force(0, 0)
                            if cooldown > 0:
                                sandbox.apply_agent_force(0, 0)
                            else:
                                next_sw = "C"
        else:
            # Cannot proceed to C, adjust movement to B
            tx, ty = _zone_center(sandbox, "B")
            x, y = sandbox.get_agent_position()
            dx = tx - x
            dy = ty - y
            dist = math.hypot(dx, dy)
            if dist > 0.5:
                force_mag = min(mf * 0.8, 20.0 * dist)
                fx = force_mag * dx / dist if dist > 1e-6 else 0
                fy = force_mag * dy / dist if dist > 1e-6 else 0
                sandbox.apply_agent_force(fx, fy)
            else:
                sandbox.apply_agent_force(0, 0)

    if next_sw in ["A", "B", "C"]:
        tx, ty = _zone_center(sandbox, next_sw)
        x, y = sandbox.get_agent_position()
        dx = tx - x
        dy = ty - y
        dist = math.hypot(dx, dy)

        if dist > 0.5:
            force_mag = min(mf * 0.8, 20.0 * dist)
            fx = force_mag * dx / dist if dist > 1e-6 else 0
            fy = force_mag * dy / dist if dist > 1e-6 else 0
            sandbox.apply_agent_force(fx, fy)
        else:
            if is_inside_zone(sandbox, x, y, next_sw):
                vx, vy = sandbox.get_agent_velocity()
                speed = math.hypot(vx, vy)
                if speed > 0.03:
                    sandbox.apply_agent_force(-5.5 * vx, -5.5 * vy)
                else:
                    fx = 10.0 * dx - 5.5 * vx
                    fy = 10.0 * dy - 5.5 * vy
                    mag = math.hypot(fx, fy)
                    if mag > mf:
                        fx, fy = fx * mf / mag, fy * mf / mag
                    sandbox.apply_agent_force(fx, fy)
